# ---------------------------------------------------------------- Beyond the textbook
d.sec('14.z-beyond-text')
b('Conditional probability P(A | B)?', r'\(P(A \mid B) = \dfrac{P(A \cap B)}{P(B)}\)' + ', P(B) > 0: the probability of A given that B has occurred (the sample space shrinks to B)')
b('Multiplication rule?', T('P(A ∩ B) = P(A) · P(B | A) = P(B) · P(A | B)'))
b('Independent events: definition and test?', T('P(A ∩ B) = P(A) · P(B)') + ' (equivalently P(A | B) = P(A)). Independent is not the same as mutually exclusive')
b('Trap: mutually exclusive vs independent?', 'If P(A), P(B) > 0 and A, B are mutually exclusive, then P(A ∩ B) = 0 ≠ P(A)P(B): they are ' + X('dependent') + '<br>Exclusive events are the most dependent: if one occurs, the other cannot')
b('Two dice: P(sum 8 | first die is 3)?', 'Given a 3, the second must be 5: ' + N('1/6'))
b('Two independent events with P(A) = 0.3, P(B) = 0.4: P(A ∪ B)?', '0.3 + 0.4 − 0.12 = ' + N('0.58') + ' (or 1 − 0.7 × 0.6)')
